// src/dsht-plugin-shared/deep-merge.ts
function isMergeableObject(v) {
  return v !== null && typeof v === "object" && !Array.isArray(v);
}
function deepMergeIncoming(low, high) {
  const out = { ...low };
  for (const [k, v] of Object.entries(high)) {
    const prev = out[k];
    if (isMergeableObject(prev) && isMergeableObject(v)) {
      out[k] = deepMergeIncoming(prev, v);
    } else {
      out[k] = v;
    }
  }
  return out;
}

