var TH_MSG_TAG = "__dsht_th";
function parseIncomingMessage(data) {
  if (data === null || typeof data !== "object") return null;
  const d = data;
  if (d[TH_MSG_TAG] !== true) return null;
  if (typeof d.scriptId !== "string" || typeof d.secret !== "string") return null;
  if (d.th === "call") {
    if (typeof d.callId !== "number" || typeof d.api !== "string" || !Array.isArray(d.args)) return null;
    return d;
  }
  if (d.th === "status") {
    if (d.phase !== "loading" && d.phase !== "running" && d.phase !== "failed") return null;
    return d;
  }
  if (d.th === "missing" && typeof d.api === "string") return d;
  if (d.th === "script-error" && typeof d.error === "string") return d;
  if (d.th === "toast" && typeof d.message === "string") return d;
  if (d.th === "ui") return d;
  if (d.th === "console" && typeof d.level === "string" && typeof d.message === "string") return d;
  return null;
}
function getStringHash(str) {
  let hash = 0;
  if (!str.length) return hash;
  for (let i = 0; i < str.length; i++) {
    hash = (hash << 5) - hash + str.charCodeAt(i) | 0;
  }
  return hash;
}
function getButtonEventId(scriptId, buttonName) {
  return `${scriptId}_${getStringHash(buttonName)}`;
}
