// src/dsht-rp-ui/src/client/composer-enter-fix.ts
function installComposerEnterFix() {
  const isTouch = () => {
    try {
      return window.matchMedia("(pointer: coarse)").matches;
    } catch {
      return false;
    }
  };
  const handler = (e) => {
    if (!isTouch()) return;
    if (e.key !== "Enter" || e.shiftKey || e.ctrlKey || e.metaKey) return;
    if (e.isComposing || e.keyCode === 229) return;
    if (document.querySelector("[data-lexical-composer-menu]") !== null) return;
    const target = e.target;
    if (target === null) return;
    const composer = target.closest("[data-composer-input]");
    if (composer === null) return;
    e.preventDefault();
    e.stopImmediatePropagation();
    document.execCommand("insertLineBreak", false);
  };
  document.addEventListener("keydown", handler, true);
  const setHint = () => {
    if (!isTouch()) return;
    document.querySelectorAll("[data-composer-input]").forEach((el) => {
      el.enterKeyHint = "enter";
    });
  };
  setHint();
  const observer = new MutationObserver(() => setHint());
  observer.observe(document.body, { childList: true, subtree: true });
}

